mapper.select:
SELECT EXISTS (
    SELECT 1 FROM enrollments
     WHERE student_id  = #{studentId}
       AND class_id    = #{classId}
       AND status_code = 'ACTIVE'
)

mapper.update:
UPDATE enrollments
   SET status_code = 'ENDED',
       end_date    = #{endDate}
 WHERE enrollment_id = #{enrollmentId}
